        "reversed": "该有的那场坦诚对话一直没发生，两人都在回避真正的清算；或者一方（也可能是你）死死抓着旧账不放，无法原谅，让关系困在过去出不来。也可能是你听不见内心对这段关系真实的判断，用「应该」压过了「我到底要不要」。"
