        "reversed": "困在自我批判的循环里——用旧的错误反复鞭打自己，把「审判」变成了永不结案的自我审讯。或者相反，用逃避和麻木盖住那个要你成长的内在召唤。逆位在说：你欠自己的不是又一轮定罪，而是一次真正的赦免。"
