        "upright": "感情上是在关系与生活其他部分(工作、家庭)之间找平衡，或灵活地处理关系中的起伏。也可能是同时权衡多段关系/选择。",
        "reversed": "可能是关系被其他事挤到失衡、无暇经营；或在多个对象间摇摆、无法专注。"
