    "suit": "pentacles",
    "status": "approved",
    "reviewNotes": "",
    "coreEnergy": {
      "oneLine": "紧紧抱住拥有的，不敢松手。",
      "expanded": "星币四是土元素的『抓紧与保守』——一个人端坐城前，双手死死抱住一枚金币，头顶顶着一枚、双脚各踩一枚。星币三的成果有了，星币四开始死守它。这团能量的核心是『因为怕失去，而把拥有的攥得太紧』。它有稳定、安全、节俭的一面，也有吝啬、控制、不敢冒险、被安全感绑架的一面。它提醒你：守住是对的，但攥太紧会让你既不敢给出、也不敢接受新的。"
    },
