        "upright": "事业上是守住现有的地位和成果、稳扎稳打、不冒险——安全但可能停滞。提醒你别因守成而错过成长。",
        "reversed": "可能是过度保守错失机会、抓着旧的不放；或开始愿意松手、尝试新的。"
