        "step1_energy": "第一步·抓核心能量：星币骑士的核心正是『靠踏实、有耐心的持续努力，一步一步把事情做完』——他是长期主义、有始有终的化身。",
        "step2_projection": "第二步·投射到领域：放到你『长期目标枯燥、快没耐心』的处境上——星币骑士恰恰是你此刻需要召唤的能量：他望着已经犁好的田，一垄一垄，不急不躁。他知道成果不在某一次冲刺里，而在日复一日稳定的耕耘中。你的『没耐心』，是想要风火骑士的速度感，而这件事需要的是土骑士的稳。",
