        "step1_energy": "第一步·抓核心能量:权杖侍从正位是旺盛的好奇与探索,而逆位正是『三分钟热度、样样浅尝辄止、缺乏方向』。",
        "step2_projection": "第二步·投射到领域:放到你『兴趣多但做不久』的状态上——你体现的是权杖侍从的两面:正面是可贵的好奇心和活力(别否定它),逆位则是热情来得快去得也快、还没深入就转向下一个。",
        "step3_action": "第三步·落地建议:给你的行动是——保留侍从的好奇(这是天赋),但给它加一根『轴』:允许自己广泛尝试,同时挑一到两个真正让你眼睛发亮的,刻意多坚持一步、探进去一层。三分钟热度本身不是罪,可惜的是从不给任何一颗种子长大的时间。"
